// ph_masks[l] covers the low 8*min(l, 8) bits of a folded window word
const ph_masks = [
	u64(0),
	u64(255),
	u64(65535),
	u64(16777215),
	u64(4294967295),
	u64(1099511627775),
	u64(281474976710655),
	u64(72057594037927935),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
	u64(18446744073709551615),
]

const ph_max_ext_len = 24

// lookup returns the MIME type for the given file extension, or '' when
// unknown. The extension may be given with or without a leading dot,
// and is compared ASCII case-insensitively without allocating.
//
// The extension is hashed and compared as up to three 8-byte windows,
// ASCII-case-folded branchlessly, so the cost does not grow with its
// length: short extensions are gathered one byte at a time, long ones
// are read with whole word loads. After the single table probe the
// finish is branchless - unknown extensions take no mispredicted
// early exits, which is what dominated their cost.
@[direct_array_access; inline]
pub fn lookup(ext string) string {
	mut i := 0
	if ext.len > 0 && ext[0] == `.` {
		i = 1
	}
	l := ext.len - i
	if l == 0 || l > ph_max_ext_len {
		return ''
	}
	mut w1 := u64(0)
	mut wl := u64(0)
	mut wm := u64(0)
	if l >= 8 {
		p := unsafe { ext.str + i }
		w1 = ph_fold(unsafe { ph_w8(p) })
		if l > 8 {
			wl = ph_fold(unsafe { ph_w8(p + l - 8) })
		}
		if l > 16 {
			wm = ph_fold(unsafe { ph_w8(p + 8) })
		}
	} else {
		// gather the bytes into one little-endian word with a rolling
		// place multiplier, so no runtime shift (and its overflow
		// check) is needed
		mut w := u64(0)
		mut pow := u64(1)
		for j in 0 .. l {
			w += u64(ext[i + j]) * pow
			pow <<= 8
		}
		w1 = ph_fold(w)
	}
	x := if l >= 8 {
		(w1 * ph_m1) ^ (wl * ph_m2) ^ (wm * ph_m3) ^ (u64(l) * ph_m4)
	} else {
		(w1 * ph_m1) ^ (u64(l) * ph_m4)
	}
	h := u32(x ^ (x >> 32))
	slot := ph_slots[((h >> 9) + ph_disp[h & 511]) & 2047]
	// branchless finish: read every window of the stored key, compare, and
	// select the result; ph_mimes[0] is the empty string for a miss
	el := int((slot >> 12) & 31)
	off := int(slot >> 17) - 1
	p := unsafe { ph_blob.str + off + 9 }
	m := ph_masks[l]
	st1 := unsafe { ph_w8(p) }
	// slot == 0 needs no test of its own: it stores el = 0, and l >= 1
	mut eq := u64(el == l)
	eq &= u64((w1 & m) == (st1 & m))
	if l > 8 {
		stl := unsafe { ph_w8(p + el - 8) }
		eq &= u64(wl == stl)
	}
	if l > 16 {
		stm := unsafe { ph_w8(p + 8) }
		eq &= u64(wm == stm)
	}
	idx := if eq != 0 { slot & 4095 } else { u32(0) }
	return ph_mimes[idx]
}
